const crypto = require('crypto');
let fs;
try { fs = require('fs'); } catch (e) {}

const item = (typeof $input !== 'undefined' && $input.first) ? $input.first() : { json: $json };
const json = item.json || $json || {};
const headers = json.headers || {};
const body = json.body || json;
const binary = item.binary || {};

let rawBody = '';
try {
  if (binary && binary.data && binary.data.data) {
    rawBody = Buffer.from(binary.data.data, 'base64').toString('utf8');
  }
} catch (e) {}

if (!rawBody && json.rawBody) {
  rawBody = json.rawBody;
}
if (!rawBody) {
  rawBody = JSON.stringify(body);
}

let secret = 'stage2_secret_key_super_secure_99';
try {
  if (typeof $env !== 'undefined' && $env && $env.WEBHOOK_SECRET) {
    secret = $env.WEBHOOK_SECRET;
  }
} catch (e) {}

const incomingSig = headers['x-webhook-signature'] || headers['x-signature'] || '';
const cleanIncoming = incomingSig.startsWith('sha256=') ? incomingSig.slice(7) : incomingSig;

const sigFromRaw = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const sigFromJson = crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex');

let isSignatureValid = false;
try {
  if (cleanIncoming) {
    if (cleanIncoming.length === sigFromRaw.length && crypto.timingSafeEqual(Buffer.from(cleanIncoming, 'hex'), Buffer.from(sigFromRaw, 'hex'))) {
      isSignatureValid = true;
    } else if (cleanIncoming.length === sigFromJson.length && crypto.timingSafeEqual(Buffer.from(cleanIncoming, 'hex'), Buffer.from(sigFromJson, 'hex'))) {
      isSignatureValid = true;
    }
  }
} catch (e) {
  isSignatureValid = false;
}

if (!incomingSig || !isSignatureValid) {
  return [{
    json: {
      validationStatus: 'INVALID_HMAC',
      httpCode: 401,
      errorResponse: {
        error: 'Unauthorized',
        message: 'Signature hash mismatch'
      }
    }
  }];
}

const orderId = body.order_id || body.orderId;
const customer = body.customer || {};
const email = customer.email || body.customer_email;
const items = Array.isArray(body.items) ? body.items : [];
const total = Number(body.total !== undefined ? body.total : (body.total_amount !== undefined ? body.total_amount : body.totalAmount));

if (!orderId || typeof orderId !== 'string') {
  return [{
    json: {
      validationStatus: 'INVALID_SCHEMA',
      httpCode: 422,
      errorResponse: {
        error: 'Unprocessable Entity',
        message: 'Validation failed: order_id is required'
      }
    }
  }];
}

if (!email || !email.includes('@')) {
  return [{
    json: {
      validationStatus: 'INVALID_SCHEMA',
      httpCode: 422,
      errorResponse: {
        error: 'Unprocessable Entity',
        message: 'Validation failed: customer.email is required and must be valid'
      }
    }
  }];
}

if (items.length > 0) {
  const calculatedSum = items.reduce((acc, item) => {
    const qty = Number(item.qty || item.quantity || 0);
    const price = Number(item.price || item.unit_price || item.unitPrice || 0);
    return acc + (qty * price);
  }, 0);

  const diff = Math.abs(calculatedSum - total);
  if (diff > 0.01) {
    return [{
      json: {
        validationStatus: 'INVALID_SCHEMA',
        httpCode: 422,
        errorResponse: {
          error: 'Unprocessable Entity',
          message: `Math validation failed: total ${total} does not match items sum ${calculatedSum.toFixed(2)}`
        }
      }
    }];
  }
}

const cacheFile = '/home/node/.n8n/processed_orders.json';
let isDuplicate = false;
try {
  let processed = [];
  if (fs && fs.existsSync(cacheFile)) {
    processed = JSON.parse(fs.readFileSync(cacheFile, 'utf8') || '[]');
  }
  if (processed.includes(orderId)) {
    isDuplicate = true;
  } else {
    processed.push(orderId);
    if (processed.length > 500) processed.shift();
    if (fs) fs.writeFileSync(cacheFile, JSON.stringify(processed), 'utf8');
  }
} catch (e) {
  globalThis.__n8nOrders = globalThis.__n8nOrders || new Set();
  if (globalThis.__n8nOrders.has(orderId)) {
    isDuplicate = true;
  } else {
    globalThis.__n8nOrders.add(orderId);
  }
}

if (isDuplicate) {
  return [{
    json: {
      validationStatus: 'DUPLICATE',
      orderId,
      message: 'Order already processed.'
    }
  }];
}

let firstName = customer.first_name || '';
let lastName = customer.last_name || '';
let fullName = customer.name || body.customer_name || '';

if (!firstName && !lastName && fullName) {
  const parts = fullName.split(' ');
  firstName = parts[0] || '';
  lastName = parts.slice(1).join(' ') || '';
} else if (!fullName && (firstName || lastName)) {
  fullName = `${firstName} ${lastName}`.trim();
}

return [{
  json: {
    validationStatus: 'VALID',
    normalizedPayload: {
      orderId,
      email,
      firstName,
      lastName,
      fullName,
      phone: customer.phone || '',
      total: String(total || 0),
      currency: body.currency || 'USD',
      createdAt: body.created_at || body.createdAt || new Date().toISOString()
    }
  }
}];
